const STATE = {}; 
export function createOrder(id, items, user) {
  if (!items || !items.length) throw new Error('empty cart');
  const total = items.reduce((s, i) => s + i.price * i.qty, 0);
  STATE[id] = { id, items, user, total, status: 'pending', createdAt: Date.now() };
  return STATE[id];
}
export function payOrder(id, channel) {
  const o = STATE[id]; if (!o) throw new Error('no order');
  if (o.status !== 'pending') throw new Error('bad state: ' + o.status);
  o.status = 'paid'; o.channel = channel;
  return o;
}
export function cancelOrder(id, reason) {
  const o = STATE[id]; if (!o) throw new Error('no order');
  if (o.status === 'shipped') throw new Error('cannot cancel shipped');
  o.status = 'cancelled'; o.cancelReason = reason;
  return o;
}
export function shipOrder(id) {
  const o = STATE[id]; if (!o) throw new Error('no order');
  if (o.status !== 'paid') throw new Error('must be paid first');
  o.status = 'shipped'; o.shippedAt = Date.now();
  return o;
}
export function getOrder(id) { return STATE[id] || null; }

