const USERS = {};
export function register(name, email, password) {
  if (!email.includes('@')) throw new Error('bad email');
  if (USERS[email]) throw new Error('duplicate');
  USERS[email] = { name, email, hash: Buffer.from(password).toString('base64'), createdAt: Date.now() };
  return { email, name };
}
export function login(email, password) {
  const u = USERS[email]; if (!u) throw new Error('no user');
  if (u.hash !== Buffer.from(password).toString('base64')) throw new Error('bad password');
  return { email: u.email, name: u.name };
}
export function profile(email) { return USERS[email] || null; }

src/payments.js:
const LEDGER = [];
export function chargeA(card, amount) {
  if (!card || card.length < 8) throw new Error('invalid card');
  const rec = { channel: 'A', card: card.slice(-4), amount, at: Date.now() };
  LEDGER.push(rec); return rec;
}
export function chargeB(token, amount) {
  if (!token) throw new Error('missing token');
  const rec = { channel: 'B', token, amount, at: Date.now() };
  LEDGER.push(rec); return rec;
}
export function refund(rec, amount) {
  if (amount > rec.amount) throw new Error('refund > charge');
  const r = { ...rec, refund: amount, at: Date.now() };
  LEDGER.push(r); return r;
}
export function ledger() { return [...LEDGER]; }

