const STOCK = {};
export function addSku(sku, qty) { STOCK[sku] = (STOCK[sku] || 0) + qty; return STOCK[sku]; }
export function reserve(sku, qty) {
  const cur = STOCK[sku] || 0;
  if (cur < qty) throw new Error('insufficient: ' + sku);
  STOCK[sku] = cur - qty; return STOCK[sku];
}
export function release(sku, qty) { STOCK[sku] = (STOCK[sku] || 0) + qty; return STOCK[sku]; }
export function stock(sku) { return STOCK[sku] || 0; }

