import { ledger } from './payments.js';
export function dailyTotal(day) {
  return ledger().filter((r) => new Date(r.at).toISOString().slice(0, 10) === day)
    .reduce((s, r) => s + (r.amount || 0) - (r.refund || 0), 0);
}
export function byChannel() {
  const out = {};
  for (const r of ledger()) out[r.channel] = (out[r.channel] || 0) + r.amount;
  return out;
}
export function csv() {
  return ledger().map((r) => [r.at, r.channel, r.amount, r.refund || 0].join(',')).join('
');
}

