const SEEN = new Set();
export function handleCallback(payload, signature) {
  if (!payload || !payload.id) throw new Error('bad payload');
  if (SEEN.has(payload.id)) return { deduped: true };
  if (signature !== sign(payload)) throw new Error('bad signature');
  SEEN.add(payload.id);
  return { accepted: true, id: payload.id };
}
function sign(p) { return 'sig-' + p.id; }

