import { ledger } from './payments.js';
const JOBS = [];
export function register(name, fn, intervalMs) { JOBS.push({ name, fn, intervalMs, lastRun: 0 }); }
export function tick(now) {
  const ran = [];
  for (const j of JOBS) if (now - j.lastRun >= j.intervalMs) { j.fn(now); j.lastRun = now; ran.push(j.name); }
  return ran;
}
export function pendingCount() { return ledger().filter((r) => !r.refund && r.channel === 'B').length; }

