import * as orders from './orders.js';
import * as users from './users.js';
import * as payments from './payments.js';
const ROUTES = {
  'POST /orders': orders.createOrder,
  'POST /orders/pay': orders.payOrder,
  'POST /users/register': users.register,
  'POST /users/login': users.login,
  'POST /pay/charge': payments.chargeA,
  'GET /reports/by-channel': payments.byChannel,
};
export function dispatch(route, payload) {
  const fn = ROUTES[route]; if (!fn) throw new Error('no route: ' + route);
  return fn(payload);
}
